import{_ as r,l as i,o as e,c as s,v as t,p as l,x as o,d,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"校准与矩匹配","description":"","frontmatter":{"title":"校准与矩匹配","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/calibration-moments.md","filePath":"econ/calibration-moments.md","lastUpdated":1789023840000}'),p={name:"econ/calibration-moments.md"};function E(h,a,u,_,A,B){const n=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="校准与矩匹配" tabindex="-1">校准与矩匹配 <a class="header-anchor" href="#校准与矩匹配" aria-label="Permalink to &quot;校准与矩匹配&quot;">​</a></h1><div class="epigraph"><p>先用长期或微观矩钉住能钉住的参数，再用模型周期矩当检验，而不是一次极大似然吃掉全部。</p><footer>—— Kydland and Prescott, Time to Build and Aggregate Fluctuations, Econometrica 1982；Hansen and Heckman 对校准的批评；Smets and Wouters 作为对照的似然传统</footer></div><p><a href="/econ/projection-methods">上一课</a>使非线性模型可算。可算不等于参数已知。本课缺口是<strong>校准</strong>：哪些参数从稳态或微观取，哪些留给周期矩去对。不重写投影的基，不把贝叶斯估计提前做完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Kydland–Prescott 1982：资本份额、折旧、贴现从长期平均与稳态关系取；技术冲击的自回归与方差去对产出、工时、投资的二阶矩。模型是实验室，矩是实验报告，不是「所有参数都自由估」。Hansen–Heckman 指出：校准回避了识别与标准误。缺口是把这种分工写清楚，而不是宣布校准过时或神圣。</p><p><span class="marginnote">矩匹配可以正式化成间接推断或 SMM（McFadden、Smith、Gourieroux–Monfort–Renault）。本课先讲宏观校准的实践结构，后课才把似然接上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>稳态矩：\\(\\beta\\) 对实际利率，$ \\alpha$ 对资本份额，\\(\\delta\\) 对投资/资本。微观：Frisch 弹性、风险厌恶、调整成本有时从微观研究取先验，而不是从宏观 IRF 估。剩下的冲击参数去对 HP 滤波后的标准差与同期相关——下一课才讲滤波本身，本课只说「周期矩」是目标。过度识别：矩多于剩余参数时，加权距离给出一个评分；权重矩阵选不好，匹配会偏。</p>',8)),(e(),l(m,null,{default:o(()=>[c(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SS%5B%22%E7%A8%B3%E6%80%81%20%2F%20%E5%BE%AE%E8%A7%82%E7%9F%A9%22%5D%20--%3E%20PIN%5B%22%E9%92%89%E4%BD%8F%E7%BB%93%E6%9E%84%E5%8F%82%E6%95%B0%22%5D%0A%20%20PIN%20--%3E%20CYC%5B%22%E5%91%A8%E6%9C%9F%E4%BA%8C%E9%98%B6%E7%9F%A9%22%5D%0A%20%20CYC%20--%3E%20REST%5B%22%E5%89%A9%E4%BD%99%E5%86%B2%E5%87%BB%E5%8F%82%E6%95%B0%22%5D%0A%20%20REST%20--%3E%20TEST%5B%22%E6%9C%AA%E7%94%A8%E7%9F%A9%E5%BD%93%E6%A3%80%E9%AA%8C%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>代表性 RBC 常过度承诺劳动波动；后来 NK 用粘性与需求冲击补矩——那是模型扩充，不是把校准改成「随便加冲击直到拟合」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是参数分工。长期增长与分配的参数若用周期噪声去估，会与增长事实打架。反过来，用稳态钉死的参数若其实在周期里 identifiably 活动（例如调整成本），校准会把识别推给冲击，看起来拟合很好，结构是错的。Lucas 批判：校准若依赖政策不变的矩，换政策后矩会变，实验室的反事实要靠结构，不靠额外自由参数。</p><p>Smets–Wouters 把许多名义与实际摩擦同时放进似然，是另一端：少依赖「先钉死再检验」，多依赖先验与全部样本路径。两课相邻，不是互相取消。</p><p><span class="marginnote">Kydland and Prescott, <em>Econometrica</em> 50(6), 1982。Prescott 的「Theory Ahead of Business Cycle Measurement」把校准写成方法论宣言。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 HP 滤波的 \\(\\lambda\\) 当校准对象来辩。不估计贝叶斯后验。也不做量化栏的资产定价矩（股权溢价已在主干）：这里的矩是宏观总量的周期矩。过度拟合冲击过程可以复制任意谱，校准纪律是限制冲击种类。</p><p>后课默认：校准 = 稳态/微观钉结构 + 周期矩对冲击（或少数弹性）。下一课：同一套线性 DSGE，用贝叶斯吃时间序列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>校准分工：长期/微观钉结构，周期矩检验或对冲击。</li><li>矩匹配可升格为 SMM；标准误与识别仍要面对。</li><li>与似然传统对照，不互相抹掉。</li><li>出处：Kydland and Prescott, <em>Econometrica</em> 1982。</li></ul>',10))])}const S=r(p,[["render",E]]);export{P as __pageData,S as default};
